 "CREATE TABLE {$wpdb->prefix}amanah_seo_ai_tasks (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,task_identifier varchar(100) NOT NULL,task_type varchar(100) NOT NULL,provider_id bigint(20) unsigned NULL,model_identifier varchar(191) NULL,status varchar(30) NOT NULL,request_data longtext NULL,result_data longtext NULL,error_category varchar(100) NULL,created_at datetime NOT NULL,completed_at datetime NULL,PRIMARY KEY(id),UNIQUE KEY task_identifier(task_identifier),KEY provider_id(provider_id),KEY status(status),KEY task_type(task_type)) {$c};",
 "CREATE TABLE {$wpdb->prefix}amanah_seo_ai_usage (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,ai_task_id bigint(20) unsigned NOT NULL,provider_id bigint(20) unsigned NULL,model_identifier varchar(191) NULL,input_tokens bigint(20) unsigned NULL,output_tokens bigint(20) unsigned NULL,total_tokens bigint(20) unsigned NULL,usage_status varchar(30) NOT NULL,estimated_cost decimal(20,8) NULL,cost_status varchar(30) NOT NULL,currency varchar(10) NULL,pricing_source varchar(100) NULL,created_at datetime NOT NULL,PRIMARY KEY(id),KEY ai_task_id(ai_task_id),KEY provider_id(provider_id)) {$c};"); foreach($t as $sql)dbDelta($sql); }
 public static function installBackgroundJobs( \wpdb $wpdb ): void { require_once ABSPATH.'wp-admin/includes/upgrade.php'; $c=$wpdb->get_charset_collate(); $t=$wpdb->prefix.'amanah_seo_jobs'; dbDelta("CREATE TABLE {$t} (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,job_id varchar(64) NOT NULL,job_type varchar(100) NOT NULL,status varchar(30) NOT NULL,priority varchar(20) NOT NULL,payload longtext NOT NULL,result_data longtext NULL,attempt_count int(10) unsigned NOT NULL DEFAULT 0,max_attempts int(10) unsigned NOT NULL DEFAULT 3,scheduled_at datetime NOT NULL,started_at datetime NULL,completed_at datetime NULL,timeout_seconds int(10) unsigned NOT NULL DEFAULT 300,idempotency_key varchar(191) NOT NULL,worker_id varchar(64) NULL,lock_acquired_at datetime NULL,lease_expires_at datetime NULL,cancellation_requested tinyint(1) NOT NULL DEFAULT 0,error_category varchar(100) NULL,error_message text NULL,progress_processed bigint(20) unsigned NOT NULL DEFAULT 0,progress_total bigint(20) unsigned NOT NULL DEFAULT 0,progress_percent decimal(6,2) NOT NULL DEFAULT 0,created_at datetime NOT NULL,updated_at datetime NOT NULL,PRIMARY KEY(id),UNIQUE KEY job_id(job_id),UNIQUE KEY idempotency_key(idempotency_key),KEY status_scheduled(status,scheduled_at),KEY priority_scheduled(priority,scheduled_at),KEY lease_expires_at(lease_expires_at)) {$c};"); }
